(1, '1', '49', 'Young Ip Man : Crisis Time PREMIERE', 'Young Ip Man : Crisis Time PREMIERE', '2', 'NULL', 'http://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1652858494_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1654526817_top_tvshowpotrait_v1.png', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/MSCCV20220324094512620000.jpg', '2022-05-07 20:00:00', '2022-05-07 21:29:00', NULL, 'N', '2022-05-13 00:00:00', '2023-02-27 07:19:00', '/top/top_tvshow/inactived_toptvshow'),
(2, '2', '100', 'Cleaning Up Promo Video', 'Three cleaners at a securities firm try to forge a new destiny for themselves and dive into the world of stocks after overhearing insider information. A remake of the British television series of the same name, "Cleaning Up" starring Yum Jung-ah, Jeon So-min & Kim Jae-hwa!', '2', '1', 'http://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1655973193_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1655973228_top_tvshowpotrait_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/1655973260_top_tvshowpopup_v1.jpg', '2022-06-19 20:15:00', '2022-06-19 21:29:00', NULL, 'Y', '2022-06-23 15:25:33', '2023-02-27 07:19:04', '/top/top_tvshow/insert_toptvshow'),
(3, '2', '59', 'Eve Promo Video', '"Eve" depicts the story of a 2 trillion divorce lawsuit that shocks the entire nation, of which, at the center of the lawsuit is Lee Ra-el, the daughter of the chaebol family with a fatal charm.', '2', '7', 'http://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1655975276_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1655975935_top_tvshowpotrait_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/1655975954_top_tvshowpopup_v1.jpg', '2022-06-23 20:15:00', '2022-06-23 21:29:00', NULL, 'Y', '2022-06-23 16:00:37', '2026-09-01 03:33:53', '/top/top_tvshow/insert_toptvshow'),
(4, '2', '89', 'Home for Summer Promo Video', 'Never giving up hope... Geum Hee (Lee Young Eun) and Joon Ho (Kim Sa Kwon) has been married for the past 10 years. Geum Hee supported Joon Ho along the way of becoming a successful plastic surgeon. Their marriage and happiness are threatened when Joon Ho meet Sang Mi (Lee Chae Young), who is a divorcee and she wants Joon Ho even though he is already married. Meanwhile, Sang Won (Yoon Sun Woo) is a chef and the younger brother of Sang Mi. He is a sympathetic and kind person but due to his painful experiences of being dumped by the woman he loved, his personality seems cold.', '2', '6', 'http://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1655976171_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1655976195_top_tvshowpotrait_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/1655976222_top_tvshowpopup_v1.jpg', '2022-06-20 19:03:00', '2022-06-20 21:24:00', NULL, 'Y', '2022-06-23 16:14:56', '2026-09-01 03:33:53', '/top/top_tvshow/insert_toptvshow'),
