(31, '1', '102', 'Podcastis Season 3', 'Monica Rachel di temani seorang Praktisi Supranatural bernama Anna Anderson, mengundang seorang narasumber untuk menceritakan kisah seram yang mereka alami. Anna akan menggunakan kemampuannya untuk menerawang kejadian & setiap sosok yang ada dalam cerita narasumber.', '1', 'NULL', 'https://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1730793301_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1730793409_top_tvshowpotrait_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/1730793347_top_tvshowpopup_v1.jpg', '2024-11-01 20:00:00', '2024-11-01 20:59:00', '', 'N', '2022-10-07 13:00:11', '2024-11-07 23:05:19', '/top/top_tvshow/inactived_toptvshow'),
