(48, '5', '102', 'Gerbang Dimensi', 'Tomkuu dan Mars, dua orang sahabat kecil yang terpisahkan dari jarak dan waktu kembali bertemu di sebuah tempat terbengkalai yang mencekam. Tomkuu adalah seorang “spirit ilustrator” yang gemar melukis tempat mistis. Sedangkan Mars seorang wanita yang terlahirkan dengan kemampuan supranatural.', '1', 'NULL', 'https://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1666334202_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1666255986_top_tvshowpotrait_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/1666334225_top_tvshowpopup_v1.jpg', '2022-10-31 19:00:00', '2022-11-07 19:00:00', NULL, 'N', '2022-10-20 16:26:14', '2022-11-01 09:13:27', '/top/top_tvshow/inactived_toptvshow'),
(49, '5', '102', 'Kisah Rumah Berhantu', 'LIVE Podcastis Special Halloween “Kisah Rumah Berhantu : Penunggu Tak Kasat Mata”, selain menceritakan salah satu rumah berhantu di Makassar, kamu berkesempatan untuk ceritain horrornya rumahmu dan akan diterawang oleh praktisi supranatural.', '1', 'NULL', 'https://picture.dens.tv/wp/img/top_tvshowbanner_v1/1280x720/1666334205_top_tvshowbanner_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpotrait_v1/575x1028/1666255990_top_tvshowpotrait_v1.jpg', 'https://picture.dens.tv/wp/img/top_tvshowpopup_v1/1280x720/1666334228_top_tvshowpopup_v1.jpg', '2022-10-31 20:00:00', '2022-11-07 20:58:00', NULL, 'N', '2022-10-20 16:28:12', '2022-11-01 09:13:44', '/top/top_tvshow/inactived_toptvshow'),
